#!/usr/bin/env node
// Testnet helper for the residence proof.
//   node zk.mjs credential <country> <out.json>    -> new credential + its leaf
//   node zk.mjs prove <credential.json> <gate-contract-id> <address> <now>
//                                                  -> proof args for verify_and_register
// The proof uses every credential leaf from the gate's on-chain events, so it
// matches the root the contract holds no matter who else added credentials.
// Credentials here are throwaway testnet data generated by the demo scripts.
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
// The Stellar SDK is a dependency of circuits/, so resolve it from there.
const { rpc, scValToNative } = createRequire(new URL("../../circuits/package.json", import.meta.url))("@stellar/stellar-sdk");
import { credentialLeaf, randomSecret } from "../../circuits/scripts/lib.mjs";
import { proveResidence } from "../../circuits/scripts/prove.mjs";

const PLATFORM_SCOPE = 1n;
const [cmd, ...args] = process.argv.slice(2);

if (cmd === "credential") {
  const [country, out] = args;
  const expiry = Math.floor(Date.now() / 1000) + 365 * 86400;
  const secret = randomSecret();
  const leaf = await credentialLeaf(BigInt(country), BigInt(expiry), secret);
  writeFileSync(
    out,
    JSON.stringify({ country, expiry, secret: secret.toString(), leaf: leaf.toString() }, null, 2),
  );
  console.log(leaf.toString());
} else if (cmd === "prove") {
  const [credFile, gate, address, now] = args;
  const cred = JSON.parse(readFileSync(credFile, "utf8"));
  const leaves = await chainLeaves(gate);
  const out = await proveResidence({
    country: BigInt(cred.country),
    expiry: BigInt(cred.expiry),
    secret: BigInt(cred.secret),
    leaves,
    now: BigInt(now),
    scope: PLATFORM_SCOPE,
    address,
  });
  const s = out.soroban;
  console.log(
    JSON.stringify({
      proof: s.proof,
      root: s.root,
      now: s.now,
      nullifier: s.nullifier,
      scope: s.scope,
    }),
  );
  process.exit(0);
} else {
  console.error("usage: zk.mjs credential <country> <out> | prove <cred> <gate-id> <address> <now>");
  process.exit(1);
}

async function chainLeaves(gate) {
  const server = new rpc.Server("https://soroban-testnet.stellar.org");
  const latest = await server.getLatestLedger();
  const byIndex = new Map();
  let cursor;
  let startLedger = Math.max(latest.sequence - 120_000, 5_380_900);
  for (let page = 0; page < 50; page++) {
    const filters = [{ type: "contract", contractIds: [gate] }];
    const res = await server.getEvents(cursor ? { cursor, filters, limit: 200 } : { startLedger, filters, limit: 200 });
    for (const e of res.events) {
      const t = e.topic.map((x) => scValToNative(x));
      if (t[0] === "gate" && t[1] === "credential") byIndex.set(Number(t[2]), BigInt(scValToNative(e.value).leaf));
    }
    if (res.events.length < 200) break;
    cursor = res.cursor;
  }
  const leaves = [];
  for (let i = 0; byIndex.has(i); i++) leaves.push(byIndex.get(i));
  return leaves;
}
